    },
    {
      // Meet routes: router mode
      path: '/:projectName/meet',
      name: 'meet',
      component: MeetView
    },
    {
      path: '/:projectName/meet/:meetId',
      name: 'meet-session',
      component: MeetView
    },
    {
      // Workspace routes: router mode
